  "promos": [
    {
      "title": "Burn It, You Cannot Destroy Me",
      "start_block": "B017",
      "end_block": "B040",
      "hook": "Juliana, chained and tear-stained, looks up at Catherine with cold conviction and says 'Burn it' as Catherine holds a glowing branding iron over her mother's burning book.",
      "cliffhanger": "Juliana declares 'A woman who survived. You cannot destroy me' as Catherine brandishes the glowing tong in her face, screaming 'You are lying!'",
      "why": "Starts with a defiant reversal against a sadistic villain and ends on an unresolved clash of wills with a weapon raised.",
      "context_gap": "Why Catherine is torturing Juliana with her mother's book"
    },
    {
      "title": "He Lost Me, I Was Freed",
      "start_block": "B044",
      "end_block": "B068",
      "hook": "Juliana says 'Gerald leaving me was the best thing he ever did for me' as Catherine stares down at her in the dungeon.",
      "cliffhanger": "Juliana says 'That nobody showed me more love than your entire world ever did' as Catherine grips the branding rod tighter with fury.",
      "why": "Emotional liberation speech that reframes betrayal as victory, ending on a raw declaration of love that enrages the villain.",
      "context_gap": "Who Gerald and the soldier husband are"
    },
    {
      "title": "You Will Never Make Anyone Love You",
      "start_block": "B089",
      "end_block": "B116",
      "hook": "Juliana tells Catherine 'You have never learned how to make anyone love you' as Catherine snaps and raises the branding poker like a weapon, screaming 'Silence!'",
      "cliffhanger": "Catherine plunges the glowing orange poker toward Juliana's face, stopping millimeters from her right eye as Juliana freezes.",
      "why": "Escalates from a devastating psychological takedown to a murder attempt, cutting on the most dangerous unresolved moment of the episode.",
      "context_gap": "Why Catherine has the authority to torture Juliana in a dungeon"
    }
  ],
  "moments": [
    {
      "start_block": "B017",
      "end_block": "B022",
      "kind": "hook",
      "description": "Juliana, chained and tear-stained, defies Catherine by telling her to burn her mother's ledger, shocking Catherine into confusion."
    },
    {
      "start_block": "B031",
      "end_block": "B040",
      "kind": "emotional",
      "description": "Juliana calmly tells Catherine 'Your cruelty does that for me' and declares she is a woman who survived and cannot be destroyed."
    },
    {
      "start_block": "B044",
      "end_block": "B053",
      "kind": "reveal",
      "description": "Juliana reveals Gerald leaving her was the best thing he ever did, declaring 'He lost me' with a liberated smile."
    },
    {
      "start_block": "B103",
      "end_block": "B116",
      "kind": "cliffhanger",
      "description": "Juliana tells Catherine she has to threaten a chained woman to feel powerful, and Catherine plunges the branding iron toward Juliana's eye."
    }
  ]
